// One-time import of the 11ty data files into Sanity.
//
// Run from the studio folder so it uses your Sanity CLI login:
//   cd studio-nursprep && npx sanity exec migrate-runner.mjs --with-user-token [-- --force]
//
// Passes:
//   1. categories (looked up by `id`)  2. exam stubs (looked up by `code`) → code→_id map
//   3. card images uploaded            4. full exam documents + siteSettings singleton
// Document _ids are generated by Sanity (only the singleton has a fixed id).
// Refuses to run when exams already exist unless --force, so a re-run can't
// silently overwrite edits made in Studio after the cutover.

import {createReadStream, existsSync} from 'node:fs'
import {createRequire} from 'node:module'
import {randomUUID} from 'node:crypto'
import {fileURLToPath} from 'node:url'
import {clean, examToDoc, ref} from './exam-doc.mjs'

const require = createRequire(import.meta.url)
const root = fileURLToPath(new URL('../../', import.meta.url))
const dataDir = root + 'scripts/sanity/legacy/' // original 11ty data files, kept until cleanup
const key = () => randomUUID().replace(/-/g, '').slice(0, 12)

export async function migrate(client, {force = false} = {}) {
  const raw = client.withConfig({perspective: 'raw'})
  const existing = await raw.fetch('count(*[_type == "exam"])')
  if (existing && !force) throw new Error(`${existing} exam documents already exist. Re-run with --force to overwrite them.`)

  const categories = require(dataDir + 'categories.js')
  const certs = require(dataDir + 'certs.js')
  const site = require(dataDir + 'site.js')
  const links = require(dataDir + 'boardcertsLinks.js')
  const exams = certs.map((c) => require(`${dataDir}exams/${c.code.toLowerCase()}.js`))

  // ---- 1. categories
  const catIdBy = {}
  for (const [order, c] of categories.entries()) {
    const doc = {_type: 'category', id: c.id, label: c.label, accent: c.accent, order}
    const _id = await raw.fetch('*[_type == "category" && id == $id][0]._id', {id: c.id})
    catIdBy[c.id] = _id ? (await client.createOrReplace({...doc, _id}))._id : (await client.create(doc))._id
  }
  console.log(`categories: ${Object.keys(catIdBy).length}`)

  // ---- 2. exam stubs → code→_id map (needed before content, for links between exams)
  const examIdBy = {}
  for (const e of exams) {
    const _id = await raw.fetch('*[_type == "exam" && code == $code][0]._id', {code: e.code})
    examIdBy[e.code] = _id || (await client.create({_type: 'exam', code: e.code}))._id
  }
  const resolveLink = (href) => {
    const code = /^\/certifications\/([a-z0-9-]+)\/$/.exec(href)?.[1]?.toUpperCase()
    if (!examIdBy[code]) throw new Error(`Link to unknown exam: ${href}`)
    return examIdBy[code]
  }

  // ---- 3 + 4. card image + full document per exam
  for (const [catalogOrder, c] of certs.entries()) {
    const e = exams[catalogOrder]
    const png = `${root}src/assets/images/certs/${e.code.toLowerCase()}-card.png`
    if (!existsSync(png)) throw new Error(`Missing card image ${png}`)
    const asset = await client.assets.upload('image', createReadStream(png), {filename: `${e.code.toLowerCase()}-card.png`})

    const bc = links[e.code] || {}
    const doc = examToDoc(e, {
      resolveLink,
      categoryId: catIdBy[e.cat],
      imageAssetId: asset._id,
      // name/body come from the exam page, not certs.js (agreed single source of truth)
      catalog: {questions: c.questions, blurb: c.blurb, catalogOrder},
      boardcerts: {
        slug: /\/exams\/([a-z0-9-]+)\//.exec(bc.questionBank || bc.practiceTest || '')?.[1],
        hasPracticeTest: Boolean(bc.practiceTest),
      },
    })
    await client.createOrReplace({...doc, _id: examIdBy[e.code]})
    console.log(`exam ${String(catalogOrder + 1).padStart(2)}/${certs.length} ${e.code}`)
  }

  // ---- siteSettings singleton
  const count = certs.length
  await client.createOrReplace(
    clean({
      _id: 'siteSettings',
      _type: 'siteSettings',
      title: site.title,
      description: site.description.replace(`for ${count} nursing`, 'for {count} nursing'),
      stats: site.stats,
      featuredChips: site.featuredChips.map((code) => ({_key: key(), ...ref(examIdBy[code])})),
      signIn: {
        _type: 'link',
        label: 'Sign in',
        url: 'https://app.boardcerts.com/login?utm_source=nursprep&utm_medium=referral&utm_campaign=nav&utm_content=sign_in',
      },
      signUp: {
        _type: 'link',
        label: 'Start free trial',
        url: 'https://app.boardcerts.com/signup?utm_source=nursprep&utm_medium=referral&utm_campaign=nav&utm_content=start_free_trial',
      },
      footerCtaPrimary: {_type: 'link', label: 'Question Banks', url: '#'},
      footerCtaSecondary: {_type: 'link', label: 'Talk to our team', url: '#'},
      footerLinks: ['About', 'Pass guarantee', 'Pricing', 'Contact', 'Privacy', 'Terms'].map((label) => ({_key: key(), _type: 'link', label, url: '#'})),
      boardcertsUtm: {source: 'nursprep', medium: 'referral', campaign: 'cert_pages'},
    }),
  )
  console.log('siteSettings: done')
}
